function viewOf(place,path){const key=place+':'+path;if(!views.has(key))views.set(key,{place,path,mode:'source',outlineOpen:true,hit:null,sourceScroll:0,renderScroll:0,selection:[0,0]});return views.get(key);}
function offsets(text,first,last){const lines=text.split('\n');first=Math.max(1,Math.min(lines.length,first));last=Math.max(first,Math.min(lines.length,last));const start=lines.slice(0,first-1).reduce((n,l)=>n+l.length+1,0),end=lines.slice(0,last).join('\n').length;return {first,last,start,end};}
