function revealHit(place,path){const v=viewOf(place,path),pane=$$('.doc-pane').find(p=>p.dataset.editorPane===place&&p.dataset.path===path);if(!pane||!v.hit)return;if(v.mode==='source'){const input=pane.querySelector('.source-input'),hit=pane.querySelector('.source-hit');if(hit){input.scrollTop+=hit.getBoundingClientRect().top-input.getBoundingClientRect().top-32;syncScroll(input);}input.setSelectionRange(v.hit.start,v.hit.start);input.focus();}else{const root=pane.querySelector('.document-render'),hit=root?.querySelector('.hit');if(hit)root.scrollTop+=hit.getBoundingClientRect().top-root.getBoundingClientRect().top-32;}}
function togglePreview(button){const pane=button.closest('.doc-pane'),place=pane.dataset.editorPane,path=pane.dataset.path,v=viewOf(place,path);currentPath=path;const input=pane.querySelector('.source-input'),preview=pane.querySelector('.document-render');if(input){v.sourceScroll=input.scrollTop;v.selection=[input.selectionStart,input.selectionEnd];}if(preview)v.renderScroll=preview.scrollTop;v.mode=v.mode==='source'?'render':'source';if(place==='right')renderAux();else render();restoreEditors();if(v.mode==='render'&&!v.renderVisited){revealHit(place,path);v.renderVisited=true;}else if(v.mode==='source'){const input=$$('.doc-pane').find(p=>p.dataset.editorPane===place&&p.dataset.path===path)?.querySelector('.source-input');input?.focus({preventScroll:true});}}
function sectionRange(path,heading){const lines=docs.get(path).text.split('\n'),index=lines.findIndex(l=>l===heading);if(index<0)return {first:1,last:Math.min(8,lines.length)};let end=index+1;while(end<lines.length&&!/^#{1,2} /.test(lines[end]))end++;return {first:index+1,last:end};}

function resolve(from,to){const a=from.split('/').slice(0,-1);for(const p of to.split('/')){if(p==='..')a.pop();else if(p!=='.'&&p)a.push(p);}return a.join('/');}
function relative(from,to){const a=from.split('/').slice(0,-1),b=to.split('/');while(a.length&&b.length&&a[0]===b[0]){a.shift();b.shift();}return '../'.repeat(a.length)+b.join('/');}
function notify(t){clearTimeout(noticeTimer);$('#notice').textContent=t;$('#notice').hidden=false;noticeTimer=setTimeout(()=>$('#notice').hidden=true,4000);}
function closeMenu(focus=false){$('#menu').hidden=true;if(focus&&menuOwner?.isConnected)menuOwner.focus();}
