function showAux(mode='links',path=currentPath){if(mode==='document'&&innerWidth>1100&&!app.style.getPropertyValue('--right')){const width=Math.round((innerWidth-slots.left.getBoundingClientRect().width)/2);app.style.setProperty('--right',width+'px');$('.layout-handle.right').setAttribute('aria-valuenow',width);}auxMode=mode;auxPath=path;currentPath=path;const split=rightSplitChoice??false;$('#right-bottom').hidden=!split;$('.right-split').hidden=!split;app.classList.remove('right-hidden');if(innerWidth<=1100)app.classList.add('aux-open');renderAux();}
function titleOf(id){return id.startsWith('doc:')?docs.get(id.slice(4))?.title:({search:'Поиск',graph:'Граф',topics:'Новые темы',settings:'Настройки',logs:'Журнал',mcp:'Анализ MCP',indexing:'Индексация',audits:'Аудиты'})[id];}
function openDoc(path,{side=false,line=0,last=line}={}){closeGlobal(false);if(!docs.has(path)){const draft=make(path,path.split('/').pop());draft.virtual=true;docs.set(path,draft);}currentPath=path;const place=side?'right':'main',v=viewOf(place,path);if(line)v.hit=offsets(docs.get(path).text,line,last||line);else if(!side)v.hit=null;if(side){if(!rightTabs.includes(path))rightTabs.push(path);showAux('document',path);}else{active='doc:'+path;if(!tabs.includes(active))tabs.push(active);app.classList.remove('aux-open');render();}renderTree();renderAux();renderSearchResults();if(line)revealHit(place,path);else{const e=$$('.source-input').find(e=>e.closest('.doc-pane').dataset.editorPane===place&&e.dataset.path===path);e?.focus();}}
