function treeNode(path,name,node,depth,f){if(node.file){const d=docs.get(path);if(f&&!(`${d.title} ${path}`.toLocaleLowerCase('ru').includes(f)))return '';return `<div class="node"><div class="row ${currentPath===path&&active.startsWith('doc:')?'selected':''}"><span class="spacer"></span><label title="${esc(path)}"><input type="checkbox" data-scope="${esc(path)}" ${selected.has(path)?'checked':''}><span class="nm" style="${d.color==='good'?'color:var(--good)':''}" data-open="${esc(path)}">${esc(d.title)}</span></label></div></div>`;}const kids=Object.entries(node.children||{}).sort(([a],[b])=>a.localeCompare(b,'ru')).map(([k,v])=>treeNode(path?path+'/'+k:k,k,v,depth+1,f)).join('');if(f&&!kids)return '';const leaves=[...docs.keys()].filter(p=>p.startsWith(path+'/')),all=leaves.length&&leaves.every(p=>selected.has(p)),some=leaves.some(p=>selected.has(p));return `<div class="node ${depth===0?'mod':'dir'} ${expanded.has(path)||f?'open':''}"><div class="row"><button class="caret" data-fold="${esc(path)}" aria-label="Раскрыть папку ${esc(folderNames[name]||name)}" aria-expanded="${expanded.has(path)||!!f}"><svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="2"><path d="m3 1 4 4-4 4"/></svg></button><label title="${esc(path)}/"><input type="checkbox" data-scope="${esc(path)}/" ${all?'checked':''} ${!all&&some?'data-ind="1"':''}><span class="folder-mark">▱</span><span class="nm" data-folder-open="${esc(path)}">${esc(folderNames[name]||name)}</span></label></div><div class="kids">${kids}</div></div>`;}
function renderTree(){const root={children:{}};for(const path of docs.keys()){if(docs.get(path).virtual)continue;const parts=path.split('/');let n=root;parts.forEach((p,i)=>{n.children??={};n.children[p]??={};n=n.children[p];if(i===parts.length-1)n.file=true;});}const f=$('#filter').value.trim().toLocaleLowerCase('ru');$('#tree').innerHTML='<button class="topics-row" data-action="topics"><span>✧</span>Новые темы<small>3</small></button>'+Object.entries(root.children).map(([k,v])=>treeNode(k,k,v,0,f)).join('');$$('[data-ind]').forEach(c=>c.indeterminate=true);$('#selection-summary').textContent=selected.size?`Отмечено документов: ${selected.size}`:'Весь проект';}
function tabsHTML(){return tabs.map(id=>`<span class="tab-wrap"><button role="tab" data-tab="${esc(id)}" aria-selected="${active===id}" tabindex="${active===id?0:-1}" draggable="${!id.startsWith('doc:')}">${id.startsWith('doc:')?`<span class="doc-color" style="background:var(--${docs.get(id.slice(4))?.color==='good'?'good':'accent'})" aria-hidden="true"></span>`:''}${esc(titleOf(id))}${id.startsWith('doc:')&&docs.get(id.slice(4))?.status==='dirty'?' ·':''}</button>${!['search','graph'].includes(id)?`<button class="tab-close" data-close-tab="${esc(id)}" aria-label="Закрыть вкладку ${esc(titleOf(id))}">×</button>`:''}</span>`).join('');}
function highlight(text){let code=false,front=false;return text.split('\n').map((line,i)=>{const s=esc(line);if(i===0&&line==='---'){front=true;return `<span class="metadata">${s}</span>`;}if(front){if(line==='---')front=false;return `<span class="metadata">${s}</span>`;}if(/^```/.test(line)){code=!code;return `<span class="code">${s}</span>`;}if(code)return `<span class="code">${s}</span>`;if(/^#{1,6} /.test(line))return `<span class="heading">${s}</span>`;if(/^>/.test(line))return `<span class="quote">${s}</span>`;return s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<span class="syntax-link">[$1]($2)</span>').replace(/`([^`]+)`/g,'<span class="code">`$1`</span>');}).join('\n')+'\n';}
const helpers=[['h1','H1','Заголовок 1'],['h2','H2','Заголовок 2'],['h3','H3','Заголовок 3'],['bold','B','Жирный · Ctrl+B'],['italic','I','Курсив · Ctrl+I'],['code','`код`','Код'],['block','```','Блок кода'],['bullet','•','Маркированный список'],['number','1.','Нумерованный список'],['task','☐','Задача'],['quote','❞','Цитата'],['table','Таблица','Таблица'],['link','Ссылка','Ссылка на документ · Ctrl+K']];
