function syncScroll(e){e.previousElementSibling.scrollTop=e.scrollTop;e.previousElementSibling.scrollLeft=e.scrollLeft;viewOf(e.closest('.doc-pane').dataset.editorPane,e.dataset.path).sourceScroll=e.scrollTop;}
function restoreEditors(){for(const e of $$('.source-input')){const v=viewOf(e.closest('.doc-pane').dataset.editorPane,e.dataset.path);e.scrollTop=v.sourceScroll;e.setSelectionRange(Math.min(v.selection[0],e.value.length),Math.min(v.selection[1],e.value.length));syncScroll(e);}for(const e of $$('.document-render'))e.scrollTop=viewOf(e.closest('.doc-pane').dataset.editorPane,e.dataset.path).renderScroll;}
