// A document tab carries its own view; dragging a panel header moves the whole panel.
function moveDocumentTab(path,from,to,anchor=null,after=false){
  const input=$$('.source-input').find(e=>e.dataset.path===path&&e.closest('.doc-pane').dataset.editorPane===from);
  const sourceView=viewOf(from,path);
  if(input){sourceView.selection=[input.selectionStart,input.selectionEnd];sourceView.sourceScroll=input.scrollTop;}
  const preview=$$('.document-render').find(e=>e.dataset.path===path&&e.closest('.doc-pane').dataset.editorPane===from);
  if(preview)sourceView.renderScroll=preview.scrollTop;
  if(from===to&&anchor===path)return;
  const resultsScroll=$('#work-content .results')?.scrollTop??0;
  if(from!==to)views.set(to+':'+path,{...sourceView,place:to,selection:[...sourceView.selection],hit:sourceView.hit?{...sourceView.hit}:null});
  const id='doc:'+path;
  if(from==='main'){tabs=tabs.filter(t=>t!==id);if(active===id)active=tabs.at(-1)||'search';}
  else{rightTabs=rightTabs.filter(p=>p!==path);if(auxPath===path)auxPath=rightTabs.at(-1);}
  const list=to==='main'?tabs:rightTabs,key=to==='main'?id:path,anchorKey=to==='main'&&anchor?'doc:'+anchor:anchor;
  const existing=list.indexOf(key);if(existing>=0)list.splice(existing,1);
  const index=anchorKey?list.indexOf(anchorKey):-1;list.splice(index<0?list.length:index+(after?1:0),0,key);
  currentPath=path;
  if(to==='main'){active=id;app.classList.remove('aux-open');if(!rightTabs.length)auxMode='links';}
  else{auxPath=path;showAux('document',path);}
  render();
  if(active==='search'&&$('#work-content .results'))$('#work-content .results').scrollTop=resultsScroll;
  notify(from===to?'Порядок вкладок изменён':'Вкладка документа перенесена');
}
let dragging=null;
