  if(event.button!==0||!tab)return;
  tabPointer={tab,id:event.pointerId,x:event.clientX,y:event.clientY,path:tab.dataset.rightTab||tab.dataset.tab.slice(4),from:tab.dataset.rightTab?'right':'main',started:false};
